{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회의 원인에 맞는 개선 조치를 선택할 수 있는지 평가한다. 판단 초점은 신고 목록 조회에 인덱스 추가와 조인 정리를 선택한 근거다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸다.",
          "task": "신고 목록 조회 쿼리에 인덱스를 추가하고 조인을 정리해 조회 시간을 0.4초로 줄였다.",
          "action": "실행 계획에서 확인한 전체 조인과 조회 조건을 근거로 인덱스 추가와 조인 정리를 선택한 이유를 설명한다.",
          "result": "조회 시간이 3.2초에서 0.4초로 줄어든 결과를 선택한 조치의 타당성과 연결해 설명한다."
        },
        "expectedEvidence": [
          "인덱스 추가와 조인 정리를 선택한 구체적인 판단 근거",
          "그 판단을 뒷받침하는 실행 계획의 전체 조인과 조회 조건"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄이셨을 때, 인덱스 추가와 조인 정리를 선택한 근거는 무엇이었나요?",
      "answerTip": "핵심부터 말하고 필요한 설명을 덧붙이세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 조회 문제를 인덱스 추가와 조인 정리를 선택한 근거로 구체적으로 제시한다.",
            "선택한 조치가 해당 조회의 불필요한 탐색이나 조인 부담을 줄이는 이유를 실제 조회 맥락과 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조회 속도를 높이려고 인덱스 추가와 조인 정리를 선택했다고 답하지만 판단 근거가 일반적이다.",
            "조회 문제와 선택한 조치의 관련성을 설명하나 실행 계획이나 조회 조건과의 연결이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스 추가와 조인 정리를 선택한 근거 없이 수행한 조치나 개선 수치만 반복한다.",
            "인덱스나 조인의 일반적인 정의만 말하거나 조회 병목과 관계없는 근거를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 원인에 맞는 수정 조치를 선택할 수 있는지 평가한다. 판단 초점은 알림 중복 발송을 고칠 때 잠금 키를 두기로 판단한 근거다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어왔다.",
          "task": "로그를 시간순으로 모아 스케줄러가 두 서버에서 동시에 실행되는 것을 찾고 잠금 키를 두는 방식으로 수정했다.",
          "action": "로그에서 확인한 스케줄러 동시 실행을 근거로 잠금 키가 오류 원인에 맞는 조치라고 판단한 이유를 설명한다.",
          "result": "잠금 키로 동시 실행을 제한하는 것이 알림 중복 발송을 막는 데 적합한 이유를 설명한다."
        },
        "expectedEvidence": [
          "알림 중복 발송을 고칠 때 잠금 키를 선택한 판단 근거",
          "그 판단을 뒷받침하는 두 서버의 스케줄러 동시 실행 로그"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 잠금 키로 고치셨을 때, 잠금 키를 두기로 판단한 근거는 무엇이었나요?",
      "answerTip": "핵심부터 말하고 필요한 설명을 덧붙이세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그에서 확인한 두 서버의 스케줄러 동시 실행을 잠금 키 선택의 구체적인 근거로 제시한다.",
            "잠금 키가 서버 간 중복 실행을 제한해 알림 중복 발송 원인을 해소하는 조치인 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러 중복 실행을 막으려고 잠금 키를 선택했다고 답하지만 근거가 일반적이다.",
            "잠금 키와 중복 발송의 관련성을 설명하나 두 서버의 동시 실행이라는 원인과의 연결이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금 키를 선택한 근거 없이 오류를 수정했다는 사실만 반복한다.",
            "잠금의 일반적인 개념만 설명하거나 스케줄러 동시 실행과 관계없는 이유를 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "흩어진 요청을 구현할 요구사항으로 구체화할 수 있는지 확인한다. 요구사항 정의서를 작성하며 개발 담당 팀원과 범위를 조정한 판단의 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "인터뷰에서 나온 요청을 서비스의 목적과 연결하고, 요구사항 범위를 조정한 근거를 설명한다.",
          "result": "그 근거가 포함할 요구사항과 제외할 요구사항의 경계를 명확히 하는 데 어떤 의미가 있었는지 설명한다."
        },
        "expectedEvidence": [
          "개발 담당 팀원과 요구사항 범위를 조정한 구체적인 판단 근거",
          "그 판단을 뒷받침한 인터뷰 요청이나 서비스 목적",
          "판단 근거와 포함·제외 범위 사이의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 요구사항 정의서를 작성하셨을 때, 개발 담당 팀원과 요구사항 범위를 조정한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "요구사항 범위를 조정한 근거를 실제 인터뷰 요청이나 서비스 목적과 연결해 구체적으로 설명한다.",
            "제시한 근거가 어떤 요구사항을 포함하거나 제외할지 판단하는 데 타당하게 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요구사항 범위를 조정한 근거를 제시하지만 사용자 필요나 서비스 목적에 대한 설명이 일반적이다.",
            "근거와 포함·제외 판단의 연결은 드러나지만 범위의 경계를 이해하기에는 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 범위를 조정한 근거 대신 문서 작성 사실이나 프로젝트 소개만 말한다.",
            "개발 담당자의 요청을 따랐다는 설명에 그치거나 요구사항 범위와 관계없는 근거를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황에서도 사용자가 거칠 화면 흐름을 구체적으로 설계할 수 있는지 확인한다. 화면설계서에 담은 예외 상황의 화면 흐름을 정한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 다뤘다.",
          "task": "기획 담당으로 Figma를 사용해 화면설계서 28장을 작성했다.",
          "action": "설계한 예외 상황의 화면 흐름을 짚고, 그 흐름을 정한 근거를 사용자가 마주하는 상태와 연결해 설명한다.",
          "result": "그 설계 판단으로 예외 상황에서 사용자가 보게 될 화면과 이어지는 행동이 얼마나 명확해지는지 설명한다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 흐름을 정한 구체적인 설계 근거",
          "그 근거가 된 예외 상황과 사용자의 화면 상태",
          "판단 근거와 설계한 화면 흐름 사이의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨을 때, 예외 상황의 화면 흐름을 정한 근거는 무엇이었나요?",
      "answerTip": "듣는 사람이 떠올릴 수 있게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황의 화면 흐름을 정한 근거를 사용자가 마주하는 구체적인 상태와 연결해 설명한다.",
            "제시한 근거가 예외 상황에서 보여 줄 화면과 이어지는 사용자 행동을 명확히 하는 설계 판단으로 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면 흐름을 정한 근거를 제시하지만 편의성이나 혼란 방지 같은 일반적인 설명에 머문다.",
            "근거와 예외 상황의 화면 흐름 사이의 연결은 있으나 사용자의 상태에 따른 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "화면 흐름을 정한 근거 대신 화면 수나 Figma 사용법만 설명한다.",
            "예외 상황과 관계없는 디자인 취향이나 일반적인 화면 구성 원칙만 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 투약을 멈추고 담당자에게 확인할 수 있는지 평가한다. 평소와 다른 진통제 용량을 그대로 투약하지 않기로 한 판단의 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 중 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "수술 전후 환자의 투약·처치를 담당했다.",
          "action": "처방 용량의 차이를 투약 중단과 담당의 확인이 필요한 문제로 판단한 근거를 설명한다.",
          "result": "담당의 확인 결과 입력 오류였다는 사실이 당시 판단의 근거와 어떻게 연결되는지 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈추고 담당의에게 확인하기로 판단한 근거",
          "처방 용량을 의심하게 된 비교 정보",
          "용량 차이를 확인 없이 받아들이지 않은 이유"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방 용량이 평소의 두 배였을 때, 투약을 멈추고 담당의에게 확인하기로 판단한 근거는 무엇이었나요?",
      "answerTip": "본인이 했던 일을 중심으로 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량과 처방 용량의 차이를 구체적으로 짚어 투약을 멈춘 판단과 연결한다.",
            "용량 차이를 오류로 단정하지 않으면서도 확인 전에는 투약하지 않아야 한다고 판단한 근거를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량이 평소와 달라 투약을 멈추고 확인했다고 답하지만 비교 근거가 개괄적이다.",
            "확인이 필요했던 이유를 환자 안전이나 처방 확인 원칙으로 설명하지만 당시 용량 차이와의 연결이 약하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈추고 확인하기로 판단한 근거를 제시하지 않고 입력 오류였다는 결과만 말한다.",
            "처방이 있으면 의심스러운 용량도 그대로 투약한다는 등 확인 전 중단 행동에 어긋나는 판단을 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 간호에 필요한 정보를 다음 근무자에게 빠짐없이 전달하는 판단을 평가한다. 진통제 투여 시각을 인수인계 항목으로 포함하기로 한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동의 낙상 고위험 환자 인수인계 체크리스트 개선 활동에서 사고 보고서로 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 확인했다.",
          "task": "인수인계 체크리스트에 진통제 투여 시각과 보행 보조 여부를 넣자고 제안했다.",
          "action": "진통제 투여 시각을 다음 근무자에게 전달할 정보로 판단한 근거를 설명한다.",
          "result": "진통제 투여 시각의 전달이 다음 근무자의 환자 상태 파악에 어떤 의미가 있다고 판단했는지 설명한다."
        },
        "expectedEvidence": [
          "진통제 투여 시각을 인수인계 항목에 넣자고 제안한 근거",
          "제안의 근거로 삼은 사고 보고서의 관찰 내용",
          "투여 시각과 다음 근무자의 환자 상태 파악 사이의 연결"
        ]
